import { Component, ChangeDetectionStrategy, Inject, OnInit, ChangeDetectorRef } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { globalConfiguration } from '@honoregaming/configuration';
import { DestroySubject, DialogService, kioskToken } from '@honoregaming/core';
import {
  AuthService,
  CustomerOperatorConfiguration,
  customerOperatorConfigurationToken,
  NavigationService,
  TelemetryService
} from '@honoregaming/customer-core';
import { I18nService } from '@honoregaming/i18n';
import { ContentService } from '@honoregaming/templating';
import { skip, takeUntil } from 'rxjs/operators';
import { merge } from 'rxjs';

@Component({
  selector: 'hg-landing-page',
  templateUrl: './landing-page.component.html',
  styleUrls: ['./landing-page.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LandingPageComponent extends DestroySubject implements OnInit {
  content?: string;
  title?: string;
  style?: string;
  contentKey?: string;
  loginOpen = false;
  closePopup = false;

  logoPath = this.getLogoPath();

  constructor(
    @Inject(customerOperatorConfigurationToken) private readonly operatorConfiguration: CustomerOperatorConfiguration,
    @Inject(kioskToken) public readonly isKiosk: boolean,
    private readonly route: ActivatedRoute,
    private readonly router: Router,
    private readonly contentService: ContentService,
    private readonly cdRef: ChangeDetectorRef,
    private readonly i18nService: I18nService,
    private readonly telemetryService: TelemetryService,
    private readonly navigationService: NavigationService,
    private readonly dialogService: DialogService,
    private readonly authService: AuthService
  ) {
    super();
  }

  ngOnInit(): void {
    this.route.params.pipe(takeUntil(this.destroy$)).subscribe(params => {
      this.contentKey = params['contentKey'];
      this.loadContent();
    });

    this.authService.me$.pipe(takeUntil(this.destroy$)).subscribe(me => {
      if (me) {
        this.router.navigate(['/']);
      }
    });
  }

  private getLogoPath(): string {
    const basePath = `${globalConfiguration.assetsPath}${this.operatorConfiguration.key}`;
    const kioskLogo = this.operatorConfiguration.kioskConfiguration?.desktopLogoPath ?? null;

    return this.isKiosk && kioskLogo !== null ? `${basePath}/${kioskLogo}` : `${basePath}/logo.png`;
  }

  loadContent() {
    this.contentService
      .getContent(this.contentKey ?? 'landing')
      .pipe(
        takeUntil(
          merge(this.destroy$, this.route.params.pipe(skip(1)), this.i18nService.languageChanged$.pipe(skip(1)))
        )
      )
      .subscribe({
        next: resource => {
          this.content = resource.content;
          this.style = resource.style;
          this.title = resource.title;

          this.cdRef.markForCheck();
        },
        error: _ => {
          this.router.navigate(['/']);
        }
      });
  }

  signup() {
    this.telemetryService.trackEvent('create_account');
    this.navigationService.goToSignup();
  }

  login() {
    this.telemetryService.trackEvent('login');
    this.dialogService.toggleDialog('login', true);
  }
}
